  static const double borderRadiusSm = 4.0;
  static const double borderRadiusMd = 6.0;
  static const double borderRadiusLg = 8.0;
  static const double borderRadiusXl = 12.0;
  static const double borderRadiusFull = 9999.0;
}

abstract final class SolarStack {
  static const double none = 0.0;
  static const double $2xs = 4.0;
  static const double xs = 8.0;
  static const double sm = 12.0;
  static const double md = 16.0;
  static const double lg = 20.0;
  static const double xl = 24.0;
  static const double $2xl = 28.0;
  static const double $3xl = 40.0;
}

abstract final class SolarViewport {
  static const double xs = 393.0;
  static const double sm = 768.0;
  static const double md = 1024.0;
  static const double lg = 1440.0;
  static const double xl = 1920.0;
}

abstract final class SolarZ {
  static const int base = 0;
  static const int sticky = 100;
  static const int dropdown = 200;
  static const int overlay = 300;
  static const int dialog = 400;
  static const int toast = 500;
  static const int tooltip = 600;
}

@immutable
class SolarTheme extends ThemeExtension<SolarTheme> {
  const SolarTheme({
    required this.colors,
    required this.shadows,
    required this.typeScale,
    required this.typography,
  });

  final SolarColors colors;
  final SolarShadows shadows;
  final SolarType typeScale;
  final SolarTypography typography;

  static const SolarTheme light = SolarTheme(
    colors: SolarColors.light,
    shadows: SolarShadows.light,
    typeScale: SolarType.desktop,
    typography: SolarTypography.desktop,
  );

  static const SolarTheme dark = SolarTheme(
    colors: SolarColors.dark,
    shadows: SolarShadows.dark,
    typeScale: SolarType.desktop,
    typography: SolarTypography.desktop,
  );

  /// The theme for a brightness and a viewport width.
  ///
  /// Below `SolarViewport.sm` the Mobile type scale applies, which is where the web's media query
  /// switches too. [light] and [dark] are the Desktop scale; pass
  /// `MediaQuery.sizeOf(context).width` here to follow the viewport the way the web does.
  static SolarTheme resolve({
    required Brightness brightness,
    required double width,
  }) {
    final dark = brightness == Brightness.dark;
    final mobile = width < SolarViewport.sm;
    return SolarTheme(
      colors: dark ? SolarColors.dark : SolarColors.light,
      shadows: dark ? SolarShadows.dark : SolarShadows.light,
      typeScale: mobile ? SolarType.mobile : SolarType.desktop,
      typography: mobile ? SolarTypography.mobile : SolarTypography.desktop,
    );
  }

  @override
  SolarTheme copyWith({
    SolarColors? colors,
    SolarShadows? shadows,
    SolarType? typeScale,
    SolarTypography? typography,
  }) =>
      SolarTheme(
        colors: colors ?? this.colors,
        shadows: shadows ?? this.shadows,
        typeScale: typeScale ?? this.typeScale,
        typography: typography ?? this.typography,
      );

  @override
  SolarTheme lerp(ThemeExtension<SolarTheme>? other, double t) =>
      (other is SolarTheme && t >= 0.5) ? other : this;
}
